sql = sql.replace(/```sql\n?/gi, '');  // quita ```sql o ```sql\n
sql = sql.replace(/```/g, '');         // quita ```
sql = sql.replace(/\n/g, ' ');         // reemplaza saltos de línea por espacio
sql = sql.replace(/^\s+|\s+$/g, '');   // quita espacios al inicio y final

return [{ query: sql }];

