// Nodo CODE justo después de tu consulta SQL
const data = $input.all().map(item => item.json);
return [{ json: { data } }];

// Espera exactamente dos items: el de 'Edit Fields3' (con output) y el de 'translator' (con data)
const items = $input.all();

// Verifica que haya justo dos ítems
if (items.length !== 2) {
  throw new Error(`Se esperaban exactamente 2 items, pero se recibieron ${items.length}`);
}

let output = null;
let data = null;

// Busca cada valor por su propiedad en cada item
for (const item of items) {
  if (item.json.hasOwnProperty('output')) {
    output = item.json.output;
  }
  if (item.json.hasOwnProperty('data')) {
    data = item.json.data;
  }
}

return [
  {
    json: {
      output,
      data,
    },
  },
];
